<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Conversation_Admin{
 private Orion_Conversation_Service $conversations;
 public function __construct(Orion_Conversation_Service $conversations){$this->conversations=$conversations;}
 public function render():void{if(!current_user_can('manage_woocommerce'))return;$id=absint($_GET['conversation_id']??0);echo '<section class="orion-card orion-conversations"><h2>Customer conversations</h2><p>Review every retained question and AI answer. Conversations are read-only here and follow the configured retention period.</p>';if($id){$this->render_one($id);echo '</section>';return;}$items=$this->conversations->all(150);if(!$items){echo '<p>No retained conversations yet.</p></section>';return;}echo '<table class="widefat striped"><thead><tr><th>Conversation</th><th>First question</th><th>Messages</th><th>AI gaps</th><th>Last activity</th></tr></thead><tbody>';foreach($items as$item){$url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_id'=>(int)$item['id']),admin_url('admin.php'));echo '<tr><td><a href="'.esc_url($url).'">#'.(int)$item['id'].'</a></td><td>'.esc_html(mb_substr((string)($item['first_question']??''),0,180)).'</td><td>'.(int)$item['message_count'].'</td><td>'.(int)$item['gap_count'].'</td><td>'.esc_html((string)$item['last_activity']).'</td></tr>';}echo '</tbody></table></section>';}
 private function render_one(int $id):void{$conversation=$this->conversations->get($id);if(!$conversation){echo '<p>Conversation not found.</p>';return;}$back=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations'),admin_url('admin.php'));echo '<p><a href="'.esc_url($back).'">← Back to conversations</a></p><h3>Conversation #'.$id.'</h3><p class="description">Created '.esc_html((string)$conversation['created_at']).' · Last activity '.esc_html((string)$conversation['last_activity']).'</p>';$gaps=$this->conversations->gaps($id);if($gaps){echo '<div class="notice notice-warning inline"><p><strong>AI knowledge gaps:</strong> ';foreach($gaps as$index=>$gap){if($index)echo ', ';$url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','gap_id'=>(int)$gap['id']),admin_url('admin.php'));echo '<a href="'.esc_url($url).'">#'.(int)$gap['id'].' '.esc_html(str_replace('_',' ',(string)$gap['reason_code'])).'</a>';}echo '</p></div>';}$messages=$this->conversations->messages($id,300);if(!$messages){echo '<p>No stored messages.</p>';return;}echo '<div class="orion-dialogue">';foreach($messages as$message){$role=(string)$message['role'];$label=$role==='user'?'Customer':'AI assistant';echo '<article style="margin:12px 0;padding:14px;border:1px solid #dcdcde;border-left:4px solid '.($role==='user'?'#2271b1':'#00a32a').';border-radius:6px;background:#fff"><div style="display:flex;justify-content:space-between;gap:12px"><strong>'.esc_html($label).'</strong><small>'.esc_html((string)$message['created_at']).'</small></div><div style="margin-top:8px;white-space:normal">'.nl2br(esc_html((string)$message['content'])).'</div></article>';}echo '</div>';}
}
